# EVOLVE-BLOCK-START
import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def _edge_cost(G, s, t):
    """Edge cost with None treated as prohibitive."""
    c = G[s][t].get("cost")
    return c if c is not None else 1e9


def _path_cost(G, path):
    return sum(_edge_cost(G, path[i], path[i + 1]) for i in range(len(path) - 1))


def search_algorithm(src, dsts, G, num_partitions):
    """Broadcast routing via GLOBAL k-shortest-path candidates + iterative
    congestion-penalized LP (min-cost-flow relaxation) over ALL destinations.

    1. For each destination, generate up to k alternative low-cost simple
       paths (nx.shortest_simple_paths), exposing parallel routes across
       networks that a single Dijkstra path ignores.
    2. ONE global LP: x[dst][route] = number of partitions of dst sent on
       that route, bounds [0, P]. Objective = sum(route_cost * x) plus a
       congestion penalty on edges whose GLOBAL load (across all dsts)
       approaches throughput capacity. Unlike per-dst LPs, the solver now
       jointly decides concentration (cheap shared trunks) vs spreading
       (parallel networks) for every destination at once.
    3. Penalties are recomputed from the resulting global edge loads and the
       LP re-solved for a few iterations (fixed point), approximating
       min-cost flow with convex congestion costs.
    4. Deterministic largest-remainder rounding per destination; falls back
       to all-partitions-on-cheapest-route if scipy is unavailable.
    """
    # Cost-weighted graph; None-cost edges are dropped (prohibitive).
    h = nx.DiGraph()
    for u, v, d in G.edges(data=True):
        c = d.get("cost")
        if c is not None:
            h.add_edge(u, v, cost=c,
                       throughput=d.get("throughput") or 1e9)
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))

    K = 8
    routes = {}
    for dst in dsts:
        cands = []
        try:
            for path in nx.shortest_simple_paths(h, src, dst, weight="cost"):
                cands.append(path)
                if len(cands) >= K:
                    break
        except Exception:
            pass
        if not cands:
            try:
                cands = [nx.dijkstra_path(h, src, dst, weight="cost")]
            except Exception:
                cands = [nx.dijkstra_path(G, src, dst, weight="cost")]
        routes[dst] = cands

    bc_topology = BroadCastTopology(src, dsts, num_partitions)
    P = bc_topology.num_partitions

    # Global edge universe + per-route incidence / base costs.
    edge_list = sorted({(p[i], p[i + 1])
                        for d in dsts for p in routes[d]
                        for i in range(len(p) - 1)})
    eidx = {e: i for i, e in enumerate(edge_list)}
    inc = {d: [[eidx[(p[i], p[i + 1])] for i in range(len(p) - 1)]
               for p in routes[d]] for d in dsts}
    base_cost = {d: [_path_cost(h, p) for p in routes[d]] for d in dsts}
    cap = [h[u][v]["throughput"] for u, v in edge_list]

    names = [(d, r) for d in dsts for r in range(len(routes[d]))]
    n = len(names)
    load = [0.0] * len(edge_list)
    x = None
    try:
        import numpy as np
        from scipy.optimize import linprog
        # Equality: per dst, sum over its routes of x == P.
        didx = {d: i for i, d in enumerate(dsts)}
        A_eq = np.zeros((len(dsts), n))
        for j, (d, r) in enumerate(names):
            A_eq[didx[d], j] = 1.0
        b_eq = np.full(len(dsts), float(P))
        for _ in range(4):  # fixed-point on congestion penalties
            c_vec = np.array([base_cost[d][r] for d, r in names], dtype=float)
            # penalty grows with global edge load relative to capacity
            for j, (d, r) in enumerate(names):
                pen = 0.0
                for e in set(inc[d][r]):
                    l = load[e]
                    if l > 0:
                        pen += 0.1 * (l / max(cap[e], 1e-9))
                c_vec[j] *= (1.0 + 0.5 * pen)
            res = linprog(c_vec, A_eq=A_eq, b_eq=b_eq,
                          bounds=[(0, P)] * n, method="highs")
            if not res.success or res.x is None:
                x = None
                break
            x = res.x
            new_load = [0.0] * len(edge_list)
            for j, (d, r) in enumerate(names):
                for e in inc[d][r]:
                    new_load[e] += x[j]
            if max(abs(a - b) for a, b in zip(new_load, load)) < 1e-6:
                break
            load = new_load
    except Exception:
        x = None

    # Deterministic largest-remainder rounding per destination.
    for d in dsts:
        m = len(routes[d])
        if x is not None:
            vals = [x[j] for j, (dd, r) in enumerate(names) if dd == d]
        else:
            vals = [0.0] * m
            vals[min(range(m), key=lambda r: base_cost[d][r])] = float(P)
        vals = [max(0.0, min(float(P), v)) for v in vals]
        fr = [int(round(v)) for v in vals]
        total = sum(fr)
        order = sorted(range(m), key=lambda r: -(vals[r] - fr[r]))
        k = 0
        while total < P:
            fr[order[k % m]] += 1
            total += 1
            k += 1
        while total > P:
            for r in order:
                if fr[r] > 0 and total > P:
                    fr[r] -= 1
                    total -= 1
        chosen = []
        for r in range(m):
            chosen.extend([r] * fr[r])
        for p in range(P):
            path = routes[d][chosen[p]]
            edges = [[path[i], path[i + 1], G[path[i]][path[i + 1]]]
                     for i in range(len(path) - 1)]
            bc_topology.set_dst_partition_paths(d, p, edges)

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


